.info-cards {
    display: flex;
    gap: $measure--small2;

    &--column {
        flex-direction: column;
    }
}

.info-card-v26 {
    font-size: $measure--threequarters;
    position: relative;
    display: flex;
    align-items: flex-end;
    width: 100%;
    max-width: $measure--large2 * 3;
    aspect-ratio: 1 / 1;
    padding: $measure--small2;

    &__theme__dark {
        color: $color-purewhite;
        background: $color-zinc60;
    }

    &__theme__light {
        color: $color-nearblack;
        background: $color-gray3;
    }

    &__icon {
        position: absolute;
        top: $measure--small2;
        right: $measure--small2;
        font-size: $measure--small3;
    }

    &__content {
        * {
            font-size: $measure--threequarters;
        }
    }

    &__text {
        font-weight: $font-weight-medium;
        margin-bottom: $measure--threequarters;

        &--lrg {
            @include font-family('heading');
            @include thetatype();
            line-height: 1;
            font-weight: $font-weight-bold;
        }
        &--med {
            @include font-family('heading');
            @include thetatype();
            line-height: 1;
            font-weight: $font-weight-bold;
        }
    }

    &__text-above {
        font-weight: $font-weight-bold;
        margin-top: 0;
        margin-bottom: $measure--half;
        line-height: 1.2;
    }

    &__text-below {
        margin: 0;
        line-height: 1.2;
    }
}
